create or replace TABLE KFL_PRODUCTION.DBP_DATA.MONAT (
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Monat eines Kalenderjahres, Format JJJJMM',
	KJMO_VJ NUMBER(38,0) NOT NULL COMMENT 'Der einem Kalenderjahresmonat entspreche Monat des Kalendervorjahres, Format JJJJMM',
	GJMO NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahresmonat, beginnend bei 1 im März, Format JJJJMM',
	GJMO_VJ NUMBER(38,0) NOT NULL COMMENT 'Der einem Geschäftsjahresmonat entsprechende Monat des Vorjahres, Format JJJJMM',
	KJQU NUMBER(38,0) NOT NULL,
	GJQU NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahresquartal, Format JJJJQQ',
	KJ NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahr, Format JJJJ',
	GJ NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahr, Format JJJJ',
	AKT_MO NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Monats zum laufenden Monat darstellt. Der aktuelle Monat hat den Wert 0, der vorige Monat -1 und der nächste Monat den Wert 1',
	AKT_MO_KOMPLETT NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Monats zum letzten abgeschlossenen Monat darstellt. Der aktuelle Monat hat den Wert 1, der vorige Monat 0 und der nächste Monat  den Wert 2',
	AKT_GJQU NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahresquartals  zum laufenden GJQuartal darstellt. Das aktuelle GJQuartal  hat den Wert 0, das vorige GJQuartal -1 und das nächste GJQuartal den Wert 1',
	AKT_GJQU_KOMPLETT NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines GeschäftjahresQuartals  zum letzten abgeschlossenen GJQuartal  darstellt. Das aktuelle GJQuartal  hat den Wert 1, das vorige GJQuartal  0 und das nächste GJQuartal  den Wert 2',
	AKT_KJQU NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Kalenderjahresquartals  zum laufenden KJQuartal darstellt. Das aktuelle KJQuartal  hat den Wert 0, das vorige KJQuartal -1 und das nächste KJQuartal den Wert 1',
	AKT_KJQU_KOMPLETT NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines KalenderahresQuartals  zum letzten abgeschlossenen KJQuartal  darstellt. Das aktuelle KJQuartal  hat den Wert 1, das vorige KJQuartal  0 und das nächste KJQuartal  den Wert 2',
	AKT_GJ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahres zum laufenden GJ darstellt. Das aktuelle GJ hat den Wert 0, das vorige GJ -1 und das nächste GJ den Wert 1',
	AKT_GJ_KOMPLETT NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahres zum letzten abgeschlossenen GJ darstellt. Das aktuelle GJ hat den Wert 1, das vorige GJ 0 und das nächste GJ den Wert 2',
	AKT_KJ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Kalenderjahres zum laufenden KJ darstellt. Das aktuelle KJ hat den Wert 0, das vorige KJ -1 und das nächste KJ den Wert 1',
	AKT_KJ_KOMPLETT NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Zahlenfolge, die den Abstand eines Kalenderjahres zum letzten abgeschlossenen KJ darstellt. Das aktuelle KJ hat den Wert 1, das vorige KJ 0 und das nächste KJ den Wert 2',
	MO_GJ NUMBER(38,0) NOT NULL,
	MO_KJ NUMBER(38,0) NOT NULL COMMENT 'Nummer des Monats (zwischen 1 und 12)',
	MIN_DAT DATE NOT NULL COMMENT 'das kleinste Datum des Monats',
	MAX_DAT DATE NOT NULL COMMENT 'das grösste Datum des Monats',
	GJHJ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Geschäftsjahres-Halbjahr (Format Jahr Halbjahr Bsp. 201701)',
	TD_UPDATE TIMESTAMP_LTZ(9),
	TD_INSERT TIMESTAMP_LTZ(9),
	KJMO_VVJ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kalendermonat im Vorvorjahr'
)COMMENT='Enthält Kalenderdaten auf Monatsebene'
;